package com.akhil.portfolio.auth;
import com.akhil.portfolio.security.JwtService; import com.akhil.portfolio.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.authentication.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final AuthenticationManager manager; final JwtService jwt; final AppUserRepository users; public AuthController(AuthenticationManager m,JwtService j,AppUserRepository u){manager=m;jwt=j;users=u;} @PostMapping("/login") public Token login(@Valid @RequestBody Login r){var a=manager.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));return new Token(jwt.create(a.getName()),users.findByUsername(a.getName()).orElseThrow().getRole().name());} public record Login(@NotBlank @Size(max=80)String username,@NotBlank @Size(min=8,max=128)String password){} public record Token(String token,String role){} }